import random
import itertools


class EinsteinHousesEnv:
    PETS = ['cat', 'dog', 'bird', 'fish']
    DRINKS = ['tea', 'coffee', 'juice', 'water']
    N = 4
    MAX_STEPS = 10
    HOUSE_REWARD = 0.25

    def __init__(self):
        self.rng = None
        self.pp = None
        self.dp = None
        self.clues = []
        self.clue_ptr = 0
        self.step_count = 0
        self.confirmed = [False] * self.N
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.pp = list(self.PETS)
        self.rng.shuffle(self.pp)
        self.dp = list(self.DRINKS)
        self.rng.shuffle(self.dp)
        self.clues = self._build_clues()
        self.clue_ptr = 1 if self.clues else 0
        self.step_count = 0
        self.confirmed = [False] * self.N
        self.done = False

        first_clue = self.clues[0][1] if self.clues else "No clues generated."
        obs = (
            "Four houses stand in a row, numbered 1 (left) to 4 (right). "
            "Each house has exactly one pet from {cat, dog, bird, fish} and "
            "one drink from {tea, coffee, juice, water}; every pet and every "
            "drink is used exactly once across the row.\n"
            "Goal: determine the pet and drink in every house.\n"
            f"Starting clue: {first_clue}\n"
            "Actions (send exactly one per turn):\n"
            "  CLUE                                          - reveal one more clue\n"
            "  GUESS <house 1-4> <pet> <drink>                - test one house\n"
            "  SOLVE <p1> <d1> <p2> <d2> <p3> <d3> <p4> <d4>  - submit the full row, "
            "houses 1 to 4 left to right\n"
            f"You have {self.MAX_STEPS} steps total. Reward is {self.HOUSE_REWARD} for "
            "each house you correctly pin down (via GUESS or SOLVE, awarded once per "
            "house). The episode ends once all four houses are pinned down, or when "
            "steps run out."
        )
        info = {"step": 0, "clues_remaining": max(0, len(self.clues) - self.clue_ptr)}
        return obs, info

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {"step": self.step_count}

        self.step_count += 1
        action = (action or "").strip()
        parts = action.split()
        reward = 0.0

        if not parts:
            obs = "Malformed action. Use CLUE, GUESS <house> <pet> <drink>, or SOLVE <8 tokens>."
        else:
            cmd = parts[0].upper()
            if cmd == 'CLUE':
                if self.clue_ptr < len(self.clues):
                    obs = f"Clue: {self.clues[self.clue_ptr][1]}"
                    self.clue_ptr += 1
                else:
                    obs = "No more clues available."
            elif cmd == 'GUESS' and len(parts) == 4:
                obs, reward = self._handle_guess(parts)
            elif cmd == 'SOLVE' and len(parts) == 9:
                obs, reward = self._handle_solve(parts)
            else:
                obs = "Malformed action. Use CLUE, GUESS <house> <pet> <drink>, or SOLVE <8 tokens>."

        terminated = False
        if all(self.confirmed):
            terminated = True
            self.done = True
            obs += " All houses confirmed -- solved!"

        truncated = False
        if not terminated and self.step_count >= self.MAX_STEPS:
            truncated = True
            self.done = True

        info = {
            "step": self.step_count,
            "confirmed": list(self.confirmed),
            "clues_remaining": max(0, len(self.clues) - self.clue_ptr),
        }
        return obs, reward, terminated, truncated, info

    def _handle_guess(self, parts):
        _, house_s, pet, drink = parts
        pet = pet.lower()
        drink = drink.lower()
        if not house_s.isdigit() or not (1 <= int(house_s) <= self.N):
            return f"Malformed GUESS: house must be 1-{self.N}.", 0.0
        house = int(house_s)
        if pet not in self.PETS or drink not in self.DRINKS:
            return "Malformed GUESS: unknown pet or drink name.", 0.0
        pet_ok = self.pp[house - 1] == pet
        drink_ok = self.dp[house - 1] == drink
        reward = 0.0
        if pet_ok and drink_ok and not self.confirmed[house - 1]:
            self.confirmed[house - 1] = True
            reward = self.HOUSE_REWARD
        obs = (f"House {house}: pet {'correct' if pet_ok else 'wrong'}, "
               f"drink {'correct' if drink_ok else 'wrong'}.")
        return obs, reward

    def _handle_solve(self, parts):
        tokens = [p.lower() for p in parts[1:]]
        houses = [(tokens[2 * i], tokens[2 * i + 1]) for i in range(self.N)]
        for pet, drink in houses:
            if pet not in self.PETS or drink not in self.DRINKS:
                return "Malformed SOLVE: unknown pet or drink name.", 0.0
        reward = 0.0
        n_correct = 0
        for h in range(self.N):
            pet, drink = houses[h]
            correct = (self.pp[h] == pet and self.dp[h] == drink)
            if correct:
                n_correct += 1
                if not self.confirmed[h]:
                    self.confirmed[h] = True
                    reward += self.HOUSE_REWARD
        obs = f"SOLVE result: {n_correct}/{self.N} houses fully correct."
        return obs, reward

    def _build_clues(self):
        pp, dp, rng = self.pp, self.dp, self.rng
        candidates = []
        seen = set()

        def add(c):
            if c not in seen:
                seen.add(c)
                candidates.append(c)

        for pet in self.PETS:
            h = pp.index(pet) + 1
            add(('pos_pet', pet, h))
            others = [x for x in range(1, self.N + 1) if x != h]
            add(('not_pos_pet', pet, rng.choice(others)))
        for drink in self.DRINKS:
            h = dp.index(drink) + 1
            add(('pos_drink', drink, h))
        for h in range(1, self.N):
            add(('left_pet_pet', pp[h - 1], pp[h]))
            add(('left_drink_pet', dp[h - 1], pp[h]))
        for h in range(1, self.N + 1):
            add(('same_house', pp[h - 1], dp[h - 1]))
        add(('end_pet', pp[0], 'left'))
        add(('end_pet', pp[-1], 'right'))

        rng.shuffle(candidates)

        selected = []
        for c in candidates:
            selected.append(c)
            if self._unique_solution(selected) is not None:
                break
        return [(c, self._clue_text(c)) for c in selected]

    def _unique_solution(self, clues):
        sol = None
        count = 0
        for pp in itertools.permutations(self.PETS):
            for dp in itertools.permutations(self.DRINKS):
                if all(self._evaluate(c, pp, dp) for c in clues):
                    count += 1
                    if count > 1:
                        return None
                    sol = (pp, dp)
        return sol

    @staticmethod
    def _evaluate(clue, pp, dp):
        t = clue[0]
        if t == 'pos_pet':
            return pp[clue[2] - 1] == clue[1]
        if t == 'pos_drink':
            return dp[clue[2] - 1] == clue[1]
        if t == 'not_pos_pet':
            return pp[clue[2] - 1] != clue[1]
        if t == 'left_pet_pet':
            return pp.index(clue[1]) + 1 == pp.index(clue[2])
        if t == 'left_drink_pet':
            return dp.index(clue[1]) + 1 == pp.index(clue[2])
        if t == 'same_house':
            return pp.index(clue[1]) == dp.index(clue[2])
        if t == 'end_pet':
            return (pp.index(clue[1]) == 0) if clue[2] == 'left' else (pp.index(clue[1]) == len(pp) - 1)
        return False

    @staticmethod
    def _clue_text(clue):
        t = clue[0]
        if t == 'pos_pet':
            return f"The house with the {clue[1]} is house {clue[2]}."
        if t == 'pos_drink':
            return f"The house that drinks {clue[1]} is house {clue[2]}."
        if t == 'not_pos_pet':
            return f"The {clue[1]} is not in house {clue[2]}."
        if t == 'left_pet_pet':
            return f"The {clue[1]} is immediately left of the {clue[2]}."
        if t == 'left_drink_pet':
            return f"The house that drinks {clue[1]} is immediately left of the house with the {clue[2]}."
        if t == 'same_house':
            return f"The {clue[1]} and the {clue[2]} are in the same house."
        if t == 'end_pet':
            side = 'leftmost' if clue[2] == 'left' else 'rightmost'
            return f"The {clue[1]} is in the {side} house."
        return "Unknown clue."

import random


class JewelersBalanceEnv:
    """Find the one counterfeit gem (and whether it's heavy or light) via balance-scale weighings."""

    GEMS = ["AMBER", "BERYL", "CITRINE", "DIAMOND", "EMERALD", "FLUORITE"]
    MAX_STEPS = 10
    WEIGH_BUDGET_REWARD = 0.6
    GUESS_REWARD = 0.4

    def __init__(self):
        self.rng = None
        self.fake_index = None
        self.fake_dir = None
        self.candidates = set()
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.fake_index = self.rng.randrange(len(self.GEMS))
        self.fake_dir = self.rng.choice(["HEAVIER", "LIGHTER"])
        self.candidates = {
            (i, d) for i in range(len(self.GEMS)) for d in ("HEAVIER", "LIGHTER")
        }
        self.steps = 0
        self.done = False

        gem_list = ", ".join(self.GEMS)
        obs = (
            "You are a gem appraiser. Among six gems ({}), exactly one is a "
            "counterfeit: it weighs either HEAVIER or LIGHTER than the five "
            "genuine gems (which all weigh identically). You do not know "
            "which gem or which direction.\n\n"
            "You have a two-pan balance scale. Actions (you have {} steps total):\n"
            "  WEIGH <left_group> <right_group> -- comma-separated gem names, "
            "no spaces inside a group, equal group sizes, no overlap. "
            "Example: WEIGH AMBER,BERYL CITRINE,DIAMOND\n"
            "  GUESS <gem> <HEAVIER|LIGHTER> -- your final verdict, ends the episode.\n\n"
            "Each WEIGH returns LEFT_HEAVIER, RIGHT_HEAVIER, or EQUAL. "
            "Gems left off the scale still matter -- an EQUAL result tells you "
            "something about them too. Reward comes from how much you narrow "
            "the true possibilities and from a correct final GUESS."
        ).format(gem_list, self.MAX_STEPS)
        return obs, {}

    def _gem_index(self, name):
        name = name.strip().upper()
        if name in self.GEMS:
            return self.GEMS.index(name)
        return None

    def _result_for(self, gem_idx, direction, left_idx, right_idx):
        if gem_idx in left_idx:
            return "LEFT_HEAVIER" if direction == "HEAVIER" else "RIGHT_HEAVIER"
        elif gem_idx in right_idx:
            return "RIGHT_HEAVIER" if direction == "HEAVIER" else "LEFT_HEAVIER"
        else:
            return "EQUAL"

    def step(self, action):
        if self.done:
            return "Episode already ended.", 0.0, True, False, {}

        self.steps += 1
        text = (action or "").strip()
        parts = text.split()

        if not parts:
            obs = "Empty action. Use WEIGH <left> <right> or GUESS <gem> <direction>."
            return self._maybe_truncate(obs, 0.0)

        cmd = parts[0].upper()

        if cmd == "WEIGH":
            if len(parts) != 3:
                obs = (
                    "Malformed WEIGH. Format: WEIGH <left_group> <right_group>, "
                    "e.g. WEIGH AMBER,BERYL CITRINE,DIAMOND"
                )
                return self._maybe_truncate(obs, 0.0)

            left_names = [n for n in parts[1].split(",") if n]
            right_names = [n for n in parts[2].split(",") if n]
            left_idx = [self._gem_index(n) for n in left_names]
            right_idx = [self._gem_index(n) for n in right_names]

            if (
                not left_names or not right_names
                or len(left_idx) != len(left_names) or None in left_idx
                or len(right_idx) != len(right_names) or None in right_idx
                or len(left_idx) != len(right_idx)
                or set(left_idx) & set(right_idx)
                or len(set(left_idx)) != len(left_idx)
                or len(set(right_idx)) != len(right_idx)
            ):
                obs = (
                    "Invalid weighing: groups must use real gem names, be "
                    "equal-sized, and not share a gem. Try again."
                )
                return self._maybe_truncate(obs, 0.0)

            left_idx_set, right_idx_set = set(left_idx), set(right_idx)
            actual_result = self._result_for(
                self.fake_index, self.fake_dir, left_idx_set, right_idx_set
            )

            before = len(self.candidates)
            self.candidates = {
                (i, d) for (i, d) in self.candidates
                if self._result_for(i, d, left_idx_set, right_idx_set) == actual_result
            }
            after = len(self.candidates)
            reward = self.WEIGH_BUDGET_REWARD * (before - after) / 11.0

            obs = (
                "Scale result: {}. {} gem/direction possibilities remain consistent."
            ).format(actual_result, after)
            return self._maybe_truncate(obs, reward)

        elif cmd == "GUESS":
            if len(parts) != 3 or parts[2].upper() not in ("HEAVIER", "LIGHTER"):
                obs = "Malformed GUESS. Format: GUESS <gem> <HEAVIER|LIGHTER>"
                return self._maybe_truncate(obs, 0.0)

            gem_idx = self._gem_index(parts[1])
            direction = parts[2].upper()
            if gem_idx is None:
                obs = "Unknown gem name in GUESS. Use one of: " + ", ".join(self.GEMS)
                return self._maybe_truncate(obs, 0.0)

            self.done = True
            if gem_idx == self.fake_index and direction == self.fake_dir:
                obs = "Correct! {} was the counterfeit and it was {}.".format(
                    self.GEMS[gem_idx], direction
                )
                return obs, self.GUESS_REWARD, True, False, {}
            else:
                obs = "Incorrect. The counterfeit was {} ({}).".format(
                    self.GEMS[self.fake_index], self.fake_dir
                )
                return obs, 0.0, True, False, {}

        else:
            obs = "Unrecognized command. Use WEIGH <left> <right> or GUESS <gem> <direction>."
            return self._maybe_truncate(obs, 0.0)

    def _maybe_truncate(self, obs, reward):
        if self.steps >= self.MAX_STEPS:
            self.done = True
            return obs + " Step limit reached.", reward, False, True, {}
        return obs, reward, False, False, {}

import random


class CargoBayManifestEnv:
    """Optimization game: pack hidden-weight boxes into the minimum number of bins."""

    N_ITEMS = 6
    CAPACITY = 10
    MAX_STEPS = 10
    WEIGH_BUDGET = 3
    MIN_WEIGHT = 2
    MAX_WEIGHT = 8

    def __init__(self):
        self.rng = None
        self.weights = []
        self.tags = []
        self.optimal = None
        self.steps = 0
        self.weighs_used = 0
        self.done = False

    def _tag(self, w):
        if w <= 3:
            return "light"
        if w <= 6:
            return "medium"
        return "heavy"

    def _min_bins(self, weights):
        n = len(weights)
        ws = sorted(weights, reverse=True)
        best = [n]

        def backtrack(idx, bins):
            if len(bins) >= best[0]:
                return
            if idx == n:
                best[0] = min(best[0], len(bins))
                return
            w = ws[idx]
            seen_caps = set()
            for bi in range(len(bins)):
                if bins[bi] >= w and bins[bi] not in seen_caps:
                    seen_caps.add(bins[bi])
                    bins[bi] -= w
                    backtrack(idx + 1, bins)
                    bins[bi] += w
            bins.append(self.CAPACITY - w)
            backtrack(idx + 1, bins)
            bins.pop()

        backtrack(0, [])
        return best[0]

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        while True:
            weights = [self.rng.randint(self.MIN_WEIGHT, self.MAX_WEIGHT) for _ in range(self.N_ITEMS)]
            optimal = self._min_bins(weights)
            if 2 <= optimal <= 4 and len(set(weights)) >= 3:
                break
        self.weights = weights
        self.tags = [self._tag(w) for w in weights]
        self.optimal = optimal
        self.steps = 0
        self.weighs_used = 0
        self.done = False

        tag_str = ", ".join(f"item{i}={self.tags[i]}" for i in range(self.N_ITEMS))
        obs = (
            f"CARGO BAY MANIFEST\n"
            f"Goal: pack all {self.N_ITEMS} boxes (item0..item{self.N_ITEMS - 1}) into the fewest "
            f"bins possible. Each bin holds total weight up to {self.CAPACITY}.\n"
            f"Coarse weight tags (light=2-3, medium=4-6, heavy=7-8): {tag_str}\n"
            f"Exact weights are hidden. Actions (one per step, {self.MAX_STEPS} steps total):\n"
            f"  WEIGH <item_id>       - reveal the exact weight of one item "
            f"(budget: {self.WEIGH_BUDGET} uses total)\n"
            f"  COMPARE <id> <id>     - learn '<', '>', or '=' between two items' exact weights\n"
            f"  PACK <b0>,<b1>,...    - submit one bin label per item, in item order "
            f"(e.g. PACK 0,0,1,1,2,0); episode ends on the first valid submission\n"
            f"An invalid PACK (wrong item count, non-bin token, or a bin over capacity) is "
            f"rejected with feedback and does not end the episode, but still costs a step."
        )
        info = {"steps_remaining": self.MAX_STEPS}
        return obs, info

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        action = (action or "").strip()
        parts = action.split()

        if not parts:
            return self._malformed("Empty action. Use WEIGH, COMPARE, or PACK.")

        verb = parts[0].upper()

        if verb == "WEIGH":
            return self._do_weigh(parts)
        if verb == "COMPARE":
            return self._do_compare(parts)
        if verb == "PACK":
            return self._do_pack(action)
        return self._malformed(f"Unknown action '{parts[0]}'. Use WEIGH, COMPARE, or PACK.")

    def _malformed(self, msg):
        obs = msg
        truncated = self.steps >= self.MAX_STEPS
        if truncated:
            obs += f" Step limit ({self.MAX_STEPS}) reached without a valid PACK."
        return obs, 0.0, False, truncated, {"steps_remaining": max(0, self.MAX_STEPS - self.steps)}

    def _do_weigh(self, parts):
        if len(parts) != 2 or not parts[1].isdigit():
            return self._malformed("WEIGH needs one item id, e.g. 'WEIGH 3'.")
        idx = int(parts[1])
        if not (0 <= idx < self.N_ITEMS):
            return self._malformed(f"item id must be 0..{self.N_ITEMS - 1}.")
        if self.weighs_used >= self.WEIGH_BUDGET:
            return self._malformed("WEIGH budget exhausted; use COMPARE instead.")
        self.weighs_used += 1
        obs = f"item{idx} exact weight = {self.weights[idx]}. (weighs used: {self.weighs_used}/{self.WEIGH_BUDGET})"
        return self._continue(obs)

    def _do_compare(self, parts):
        if len(parts) != 3 or not parts[1].isdigit() or not parts[2].isdigit():
            return self._malformed("COMPARE needs two item ids, e.g. 'COMPARE 1 4'.")
        a, b = int(parts[1]), int(parts[2])
        if not (0 <= a < self.N_ITEMS and 0 <= b < self.N_ITEMS) or a == b:
            return self._malformed(f"item ids must be distinct and in 0..{self.N_ITEMS - 1}.")
        wa, wb = self.weights[a], self.weights[b]
        sym = "=" if wa == wb else ("<" if wa < wb else ">")
        obs = f"item{a} {sym} item{b}"
        return self._continue(obs)

    def _continue(self, obs):
        truncated = self.steps >= self.MAX_STEPS
        if truncated:
            obs += f" Step limit ({self.MAX_STEPS}) reached without a valid PACK."
        return obs, 0.0, False, truncated, {"steps_remaining": max(0, self.MAX_STEPS - self.steps)}

    def _do_pack(self, action):
        rest = action[len("PACK"):].strip()
        tokens = [t.strip() for t in rest.split(",") if t.strip() != ""]
        if len(tokens) != self.N_ITEMS:
            return self._malformed(
                f"PACK needs exactly {self.N_ITEMS} comma-separated bin labels, one per item."
            )
        bins = {}
        for i, tok in enumerate(tokens):
            bins.setdefault(tok, []).append(i)
        for label, items in bins.items():
            total = sum(self.weights[i] for i in items)
            if total > self.CAPACITY:
                return self._malformed(
                    f"bin '{label}' holds items {items} totalling {total} > capacity "
                    f"{self.CAPACITY}. Submission rejected; try again."
                )
        used = len(bins)
        self.done = True
        if used == self.optimal:
            reward = 1.0
        elif used == self.optimal + 1:
            reward = 0.6
        elif used == self.optimal + 2:
            reward = 0.3
        else:
            reward = 0.1
        obs = (
            f"Valid packing accepted: {used} bin(s) used (optimal was {self.optimal}). "
            f"Reward = {reward:.2f}."
        )
        return obs, reward, True, False, {"bins_used": used, "optimal": self.optimal}

import random


class HeadTableSeatingEnv:
    """Deduce a hidden clockwise seating order from pairwise proximity comparisons."""

    NAMES = ["Ada", "Bram", "Cleo", "Dez", "Elin"]
    MAX_STEPS = 10

    def __init__(self):
        self._name_lookup = {n.upper(): n for n in self.NAMES}
        self.rng = None
        self.order = []
        self.step_count = 0
        self.credited = [False] * 5
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.order = self.NAMES[:]
        self.rng.shuffle(self.order)
        self.step_count = 0
        self.credited = [False] * 5
        self.done = False
        obs = (
            "HEAD TABLE SEATING DEDUCTION\n"
            "Six seats sit clockwise around a round table: seat 1 is the Host (fixed), "
            "and seats 2-6 hold five guests in a hidden order: Ada, Bram, Cleo, Dez, Elin.\n"
            "Goal: within 10 total steps, determine the exact clockwise order of seats 2-6.\n"
            "Actions (exactly one per step):\n"
            "  COMPARE <name1> <name2> -- learn which of the two guests sits closer to the "
            "Host (fewer seats clockwise from seat 1).\n"
            "  SOLVE <name1> <name2> <name3> <name4> <name5> -- submit your guess for seats "
            "2 through 6, in order.\n"
            "Each SOLVE reports how many named seats are correct and permanently banks reward "
            "for any seat you name correctly for the first time. Naming all five correctly at "
            "once ends the episode with full reward. You have 10 steps total."
        )
        return obs, {}

    def _resolve(self, token):
        return self._name_lookup.get(token.upper())

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.step_count += 1
        reward = 0.0
        terminated = False
        truncated = False

        parts = action.strip().split()
        if not parts:
            obs = "Empty action. Use 'COMPARE <name1> <name2>' or 'SOLVE <5 names>'."
        else:
            verb = parts[0].upper()
            if verb == "COMPARE" and len(parts) == 3:
                a = self._resolve(parts[1])
                b = self._resolve(parts[2])
                if a is None or b is None or a == b:
                    obs = ("Invalid COMPARE: give two distinct guest names from "
                            "Ada, Bram, Cleo, Dez, Elin.")
                else:
                    if self.order.index(a) < self.order.index(b):
                        obs = f"{a} sits closer to the Host than {b}."
                    else:
                        obs = f"{b} sits closer to the Host than {a}."
            elif verb == "SOLVE" and len(parts) == 6:
                guess = [self._resolve(t) for t in parts[1:]]
                if None in guess or sorted(guess) != sorted(self.NAMES):
                    obs = ("Invalid SOLVE: name each of Ada, Bram, Cleo, Dez, Elin "
                            "exactly once, in seat order.")
                else:
                    correct = 0
                    newly = 0
                    for i in range(5):
                        if guess[i] == self.order[i]:
                            correct += 1
                            if not self.credited[i]:
                                self.credited[i] = True
                                newly += 1
                    reward += 0.1 * newly
                    if correct == 5:
                        reward += 0.5
                        terminated = True
                        self.done = True
                        obs = f"Correct! Seats 2-6: {', '.join(self.order)}."
                    else:
                        obs = f"{correct}/5 seats correctly named. Keep deducing the rest."
            else:
                obs = ("Malformed action. Use 'COMPARE <name1> <name2>' or "
                        "'SOLVE <name1> <name2> <name3> <name4> <name5>'.")

        if not self.done and self.step_count >= self.MAX_STEPS:
            truncated = True
            self.done = True

        return obs, reward, terminated, truncated, {}

import random


class CellularAutomatonRuleEnv:
    """A hidden totalistic 1D cellular-automaton rule must be discovered via
    self-chosen probe rows, then used to extrapolate a fixed seed row forward."""

    MAX_STEPS = 10
    CELLS = 5

    def _valid_bits(self, s):
        return len(s) == self.CELLS and all(c in '01' for c in s)

    def _apply(self, state):
        L = self.CELLS
        out = []
        for i in range(L):
            left = state[i - 1]
            mid = state[i]
            right = state[(i + 1) % L]
            s = int(left) + int(mid) + int(right)
            out.append(str(self.table[s]))
        return ''.join(out)

    def _format_error(self):
        return (
            "Malformed action. Valid forms:\n"
            f"  QUERY <{self.CELLS}-bit string of 0/1>\n"
            f"  PREDICT <k> <{self.CELLS}-bit string of 0/1>   (k an integer from 1 to {self.target_k})"
        )

    def reset(self, seed=None):
        self.rng = random.Random(seed)

        while True:
            table = [self.rng.randint(0, 1) for _ in range(4)]
            if len(set(table)) > 1:
                break
        self.table = table

        self.target_k = 3

        while True:
            s0 = ''.join(self.rng.choice('01') for _ in range(self.CELLS))
            ones = s0.count('1')
            if 0 < ones < self.CELLS:
                break
        self.s0 = s0

        self.states = [s0]
        for _ in range(self.target_k):
            self.states.append(self._apply(self.states[-1]))

        self.steps = 0
        self.claimed = set()
        self.done = False

        obs = (
            "CELLULAR AUTOMATON RULE DISCOVERY.\n"
            f"There is a hidden row of {self.CELLS} cells (0/1), cyclic (the row wraps around). "
            "Each generation, every cell's new value depends ONLY on the total count of 1s among "
            "itself and its two cyclic neighbors (a number from 0 to 3) — this count-to-bit mapping "
            "is a fixed hidden rule table with exactly 4 unknown entries (for counts 0,1,2,3).\n"
            f"Fixed seed row (generation 0): {s0}\n"
            f"GOAL: predict the exact row at generation {self.target_k} (i.e. after applying the "
            "hidden rule 3 times, starting from the seed row above).\n"
            "ACTIONS (exactly one per turn):\n"
            f"  QUERY <row>       — apply the hidden rule once to a row of your choosing (any "
            f"{self.CELLS}-bit string), see the resulting next-generation row. Use this to work "
            "out the rule table.\n"
            f"  PREDICT <k> <row> — claim that the seed row's generation-k state equals <row>, for "
            f"any k from 1 to {self.target_k}. Predicting k < {self.target_k} is an optional "
            f"checkpoint (partial reward, doesn't end the game). Predicting k={self.target_k} ends "
            "the game immediately, right or wrong.\n"
            f"You have {self.MAX_STEPS} steps total (QUERY and PREDICT both count). Wrong PREDICTs "
            "tell you how many of the cells were correct, not which ones."
        )
        return obs, {}

    def step(self, action):
        if self.done:
            return "Episode already over.", 0.0, True, False, {}

        self.steps += 1
        reward = 0.0
        terminated = False
        tokens = action.strip().split()

        if not tokens:
            obs = self._format_error()
        else:
            cmd = tokens[0].upper()
            if cmd == "QUERY" and len(tokens) == 2 and self._valid_bits(tokens[1]):
                nxt = self._apply(tokens[1])
                obs = (
                    f"QUERY {tokens[1]} -> {nxt}\n"
                    f"Steps used: {self.steps}/{self.MAX_STEPS}."
                )
            elif cmd == "PREDICT" and len(tokens) == 3:
                k_str, guess = tokens[1], tokens[2]
                if k_str.isdigit() and 1 <= int(k_str) <= self.target_k and self._valid_bits(guess):
                    k = int(k_str)
                    true_state = self.states[k]
                    matches = sum(1 for a, b in zip(guess, true_state) if a == b)
                    correct = (matches == self.CELLS)

                    if k == self.target_k:
                        frac = matches / self.CELLS
                        reward = round(0.7 * frac, 4)
                        terminated = True
                        if correct:
                            obs = (
                                f"PREDICT k={k}: MATCH! All {self.CELLS} cells correct. "
                                "Final horizon reached — episode complete."
                            )
                        else:
                            obs = (
                                f"PREDICT k={k}: {matches}/{self.CELLS} cells correct. "
                                f"That was the final horizon (k={self.target_k}) — episode over."
                            )
                    else:
                        checkpoint_value = 0.15
                        if correct and k not in self.claimed:
                            self.claimed.add(k)
                            reward = checkpoint_value
                            obs = (
                                f"PREDICT k={k}: MATCH! Checkpoint reward earned. "
                                f"{matches}/{self.CELLS} cells correct."
                            )
                        elif correct and k in self.claimed:
                            obs = (
                                f"PREDICT k={k}: correct again, but this checkpoint was already "
                                "claimed (no additional reward)."
                            )
                        else:
                            obs = (
                                f"PREDICT k={k}: {matches}/{self.CELLS} cells correct. "
                                "Not an exact match — keep probing."
                            )
                else:
                    obs = self._format_error()
            else:
                obs = self._format_error()

        truncated = False
        if not terminated and self.steps >= self.MAX_STEPS:
            truncated = True
            obs += f"\nStep limit ({self.MAX_STEPS}) reached — episode ends."

        if terminated or truncated:
            self.done = True

        return obs, reward, terminated, truncated, {}

