class HollowFenLedgerEnv:
    NAMES = ["the Elder", "the Miller", "the Weaver", "the Smith",
              "the Baker", "the Cooper", "the Tanner"]
    ASK_BUDGET = 7
    N = 7  # villagers 0..6; villager 0 is the Elder, known to be a knight

    def __init__(self):
        self.rng = None
        self.types = None  # 1 = knight (truthful), 0 = knave (liar)
        self.asks_used = 0
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        while True:
            others = [self.rng.randint(0, 1) for _ in range(self.N - 1)]
            if 0 < sum(others) < self.N - 1:
                break
        self.types = [1] + others
        self.asks_used = 0
        self.steps = 0
        self.done = False
        roster = ", ".join(f"{i}={self.NAMES[i]}" for i in range(self.N))
        obs = (
            "You are investigating the village of Hollow Fen. Six residents "
            "(villagers 1-6) are each secretly a knight (always tells the "
            "truth) or a knave (always lies). Villager 0, the Elder, is "
            "known by public record to be a knight.\n"
            f"Roster: {roster}.\n"
            "ACTIONS:\n"
            "  ASK <i> <j>  - villager i is asked 'Is villager j a knight?' "
            "and answers 'yes' or 'no'.\n"
            "  GUESS <t1> <t2> <t3> <t4> <t5> <t6>  - submit villagers 1..6's "
            "types in order, each token K (knight) or N (knave). This ends "
            "the episode.\n"
            f"You may ASK at most {self.ASK_BUDGET} times before you must "
            "GUESS. Total steps (asks plus the guess) are capped at 10.\n"
            "Reward: 1/6 for each of the six villagers you correctly "
            "identify in your final GUESS."
        )
        return obs, {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}
        self.steps += 1
        action = (action or "").strip()

        ask_match = re.fullmatch(r"ASK\s+(\d+)\s+(\d+)", action, re.IGNORECASE)
        guess_match = re.fullmatch(
            r"GUESS\s+([KNkn])\s+([KNkn])\s+([KNkn])\s+([KNkn])\s+([KNkn])\s+([KNkn])",
            action, re.IGNORECASE,
        )

        if ask_match:
            i, j = int(ask_match.group(1)), int(ask_match.group(2))
            if not (0 <= i < self.N and 0 <= j < self.N):
                return self._malformed(f"Villager indices must be 0-{self.N - 1}.")
            if self.asks_used >= self.ASK_BUDGET:
                return self._malformed("No ASK actions remain; you must GUESS now.")
            self.asks_used += 1
            answer = "yes" if self.types[i] == self.types[j] else "no"
            obs = (
                f"{self.NAMES[i]} is asked 'Is villager {j} a knight?' and "
                f"answers: '{answer}'. ({self.ASK_BUDGET - self.asks_used} "
                f"asks remaining, {10 - self.steps} steps remaining.)"
            )
            if self.steps >= 10:
                self.done = True
                return obs + " No steps remain; the investigation closes.", 0.0, False, True, {}
            return obs, 0.0, False, False, {}

        if guess_match:
            guess = [1 if g.upper() == "K" else 0 for g in guess_match.groups()]
            actual = self.types[1:]
            correct = sum(1 for g, a in zip(guess, actual) if g == a)
            reward = correct / 6.0
            self.done = True
            truth = ", ".join(
                f"{self.NAMES[k]}={'knight' if t else 'knave'}"
                for k, t in enumerate(self.types) if k > 0
            )
            obs = f"You guessed {correct}/6 correctly. The truth: {truth}."
            return obs, reward, True, False, {}

        return self._malformed(
            "Malformed action. Use 'ASK <i> <j>' or "
            "'GUESS <t1> <t2> <t3> <t4> <t5> <t6>' with tokens K or N."
        )

    def _malformed(self, msg):
        if self.steps >= 10:
            self.done = True
            return msg + " No steps remain; the investigation closes.", 0.0, False, True, {}
        return msg, 0.0, False, False, {}

import re


class GroovePeriodEnv:
    VOICES = ('K', 'S', 'H')
    PERIOD_CHOICES = (5, 6, 7, 8)
    BAR_LEN = 8
    TARGET_BAR = 3
    MAX_STEPS = 10
    PROBE_MIN = 8
    PROBE_MAX = 39

    PROBE_RE = re.compile(r'^PROBE\s+([KSHksh])\s+(\d+)$')
    SUBMIT_RE = re.compile(
        r'^SUBMIT\s+K:([Xx.]{8})\s+S:([Xx.]{8})\s+H:([Xx.]{8})$'
    )

    def __init__(self):
        self.rng = None
        self.periods = {}
        self.phases = {}
        self.steps_used = 0
        self.done = False

    def _hit(self, voice, step):
        return (step % self.periods[voice]) == self.phases[voice]

    def _bar_pattern(self, voice, bar_index):
        start = bar_index * self.BAR_LEN
        return ''.join(
            'X' if self._hit(voice, start + i) else '.'
            for i in range(self.BAR_LEN)
        )

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.periods = {v: self.rng.choice(self.PERIOD_CHOICES) for v in self.VOICES}
        self.phases = {v: self.rng.randrange(self.periods[v]) for v in self.VOICES}
        self.steps_used = 0
        self.done = False

        bar0 = {v: self._bar_pattern(v, 0) for v in self.VOICES}
        t_start = self.TARGET_BAR * self.BAR_LEN
        t_end = t_start + self.BAR_LEN - 1

        lines = [
            "Three drum voices loop forever: Kick (K), Snare (S), Hi-Hat (H).",
            "Each voice hits at global step s exactly when (s mod period) == phase, "
            "for that voice's own hidden fixed period and phase (never shown directly).",
            "Bar 0 (steps 0-7) is notated below for all three voices ('X'=hit, '.'=rest):",
            f"K: {bar0['K']}",
            f"S: {bar0['S']}",
            f"H: {bar0['H']}",
            f"Goal: predict bar {self.TARGET_BAR} (steps {t_start}-{t_end}) exactly, for all three voices.",
            f"Action 'PROBE <K|S|H> <step>' reveals hit/no-hit for one voice at one step "
            f"between {self.PROBE_MIN} and {self.PROBE_MAX} (steps 0-7 are already shown above).",
            "Action 'SUBMIT K:xxxxxxxx S:xxxxxxxx H:xxxxxxxx' (8 chars of X/. per voice, in step "
            f"order for bar {self.TARGET_BAR}) grades your prediction and ends the episode.",
            f"You have {self.MAX_STEPS} actions total (probes and the submission both count). "
            "Reward is 1/3 per voice predicted exactly right in the target bar.",
        ]
        return "\n".join(lines), {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps_used += 1
        remaining = self.MAX_STEPS - self.steps_used
        text = (action or "").strip()

        m_submit = self.SUBMIT_RE.match(text)
        if m_submit:
            pred = {
                'K': m_submit.group(1).upper(),
                'S': m_submit.group(2).upper(),
                'H': m_submit.group(3).upper(),
            }
            actual = {v: self._bar_pattern(v, self.TARGET_BAR) for v in self.VOICES}
            correct_count = sum(1 for v in self.VOICES if pred[v] == actual[v])
            reward = correct_count / 3.0
            self.done = True
            report = [
                f"{v}: {'MATCH' if pred[v] == actual[v] else 'MISS'} "
                f"(yours={pred[v]} actual={actual[v]})"
                for v in self.VOICES
            ]
            obs = "Submission graded.\n" + "\n".join(report) + f"\nTotal reward: {reward:.3f}"
            return obs, reward, True, False, {}

        m_probe = self.PROBE_RE.match(text)
        if m_probe:
            voice = m_probe.group(1).upper()
            pos = int(m_probe.group(2))
            if pos < self.PROBE_MIN or pos > self.PROBE_MAX:
                obs = (
                    f"Invalid probe step {pos}: steps 0-7 are already shown above; "
                    f"choose a step between {self.PROBE_MIN} and {self.PROBE_MAX}. "
                    f"{max(remaining, 0)} actions left."
                )
                return obs, 0.0, False, remaining <= 0, {}
            hit = self._hit(voice, pos)
            obs = (
                f"Probe {voice} at step {pos}: {'HIT' if hit else 'no hit'}. "
                f"{max(remaining, 0)} actions left."
            )
            return obs, 0.0, False, remaining <= 0, {}

        obs = (
            "Could not parse that action. Use 'PROBE <K|S|H> <step>' with step in "
            f"[{self.PROBE_MIN},{self.PROBE_MAX}], or 'SUBMIT K:xxxxxxxx S:xxxxxxxx H:xxxxxxxx' "
            f"(8 chars of X/. per voice). {max(remaining, 0)} actions left."
        )
        return obs, 0.0, False, remaining <= 0, {}

