class GridBalanceEnv:
    SOURCES = ["Solar", "Wind", "Hydro", "Gas", "Coal"]
    MAX_INSPECTS = 3
    STEP_LIMIT = 10

    def __init__(self):
        self.rng = None
        self.capacities = {}
        self.costs = {}
        self.tiers = {}
        self.demand = 0
        self.optimal_cost = 0
        self.worst_cost = 0
        self.inspect_count = 0
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.capacities = {s: self.rng.randint(4, 10) for s in self.SOURCES}
        self.costs = {s: self.rng.randint(2, 9) for s in self.SOURCES}
        total_cap = sum(self.capacities.values())
        self.demand = max(6, round(total_cap * 0.6))
        self.demand = min(self.demand, total_cap - 1)

        def tier(c):
            if c <= 4:
                return "low"
            elif c <= 6:
                return "mid"
            else:
                return "high"

        self.tiers = {s: tier(self.costs[s]) for s in self.SOURCES}
        self.optimal_cost = self._merit_order_cost(self.demand, reverse=False)
        self.worst_cost = self._merit_order_cost(self.demand, reverse=True)

        self.inspect_count = 0
        self.steps = 0
        self.done = False

        lines = [
            "GRID BALANCE CONSOLE",
            "Goal: dispatch exactly " + str(self.demand) + " MWh total across the " + str(len(self.SOURCES)) +
            " sources below, minimizing total cost. Each source has a known capacity (max MWh) and a HIDDEN "
            "cost per MWh; you only see a rough cost tier for each.",
            "",
            "Sources (name: capacity MWh, cost tier):",
        ]
        for s in self.SOURCES:
            lines.append("  " + s + ": capacity=" + str(self.capacities[s]) + ", tier=" + self.tiers[s])
        lines.append("")
        lines.append("You may INSPECT at most " + str(self.MAX_INSPECTS) +
                      " sources (across the whole episode) to learn their exact cost.")
        lines.append("Actions (one per step):")
        lines.append("  inspect <Source>                     - reveal exact cost/MWh for one source")
        lines.append("  dispatch <S1>=<n1>, <S2>=<n2>, ...    - final allocation: nonnegative integer amounts, "
                      "each <= that source's capacity, summing to exactly the demand. A VALID dispatch ends the "
                      "episode; an invalid one is rejected with no penalty and does not end the episode.")
        lines.append("Cost tiers: low=2-4, mid=5-6, high=7-9 per MWh. You have " + str(self.STEP_LIMIT) +
                      " steps total.")
        return "\n".join(lines), {}

    def _merit_order_cost(self, demand, reverse=False):
        order = sorted(self.SOURCES, key=lambda s: self.costs[s], reverse=reverse)
        remaining = demand
        cost = 0
        for s in order:
            take = min(self.capacities[s], remaining)
            cost += take * self.costs[s]
            remaining -= take
            if remaining <= 0:
                break
        return cost

    def _maybe_truncate(self, obs, reward):
        if self.steps >= self.STEP_LIMIT:
            self.done = True
            return obs + " Step limit reached; episode truncated with no dispatch submitted.", reward, False, True, {}
        return obs, reward, False, False, {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        action = (action or "").strip()

        m_inspect = re.match(r"(?i)^inspect\s+([A-Za-z]+)\s*$", action)
        m_dispatch = re.match(r"(?i)^dispatch\s+(.+)$", action)

        if m_inspect:
            name = m_inspect.group(1).strip().capitalize()
            if name not in self.SOURCES:
                obs = "Unknown source '" + name + "'. Valid sources: " + ", ".join(self.SOURCES) + "."
                return self._maybe_truncate(obs, 0.0)
            if self.inspect_count >= self.MAX_INSPECTS:
                obs = "No inspections remaining (used " + str(self.inspect_count) + "/" + str(self.MAX_INSPECTS) + ")."
                return self._maybe_truncate(obs, 0.0)
            self.inspect_count += 1
            obs = (name + ": exact cost = " + str(self.costs[name]) + " per MWh. Inspections used: " +
                   str(self.inspect_count) + "/" + str(self.MAX_INSPECTS) + ".")
            return self._maybe_truncate(obs, 0.0)

        if m_dispatch:
            body = m_dispatch.group(1)
            alloc = {}
            valid = True
            for part in body.split(","):
                part = part.strip()
                if not part:
                    continue
                mm = re.match(r"(?i)^([A-Za-z]+)\s*=\s*(-?\d+)\s*$", part)
                if not mm:
                    valid = False
                    break
                name = mm.group(1).capitalize()
                amt = int(mm.group(2))
                if name not in self.SOURCES or amt < 0:
                    valid = False
                    break
                alloc[name] = alloc.get(name, 0) + amt

            if not valid:
                obs = ("Malformed dispatch. Use: dispatch Source1=amount1, Source2=amount2, ... "
                       "with nonnegative integer amounts.")
                return self._maybe_truncate(obs, 0.0)

            for name, amt in alloc.items():
                if amt > self.capacities[name]:
                    obs = "Dispatch rejected: " + name + " allocation " + str(amt) + " exceeds capacity " + \
                          str(self.capacities[name]) + "."
                    return self._maybe_truncate(obs, 0.0)

            total = sum(alloc.values())
            if total != self.demand:
                obs = "Dispatch rejected: total " + str(total) + " MWh does not equal demand " + \
                      str(self.demand) + " MWh."
                return self._maybe_truncate(obs, 0.0)

            achieved_cost = sum(alloc.get(s, 0) * self.costs[s] for s in self.SOURCES)
            self.done = True
            span = max(self.worst_cost - self.optimal_cost, 1)
            efficiency = 1.0 - (achieved_cost - self.optimal_cost) / span
            efficiency = max(0.0, min(1.0, efficiency))
            reward = 0.3 + 0.7 * efficiency
            reward = max(0.0, min(1.0, reward))
            obs = ("Dispatch accepted. Total cost = " + str(achieved_cost) + " (optimal = " +
                   str(self.optimal_cost) + ", worst feasible = " + str(self.worst_cost) +
                   "). Demand met exactly. Episode complete, reward=" + format(reward, ".2f") + ".")
            return obs, reward, True, False, {"achieved_cost": achieved_cost, "optimal_cost": self.optimal_cost}

        obs = "Unrecognized action. Use 'inspect <Source>' or 'dispatch <Source>=<amount>, ...'."
        return self._maybe_truncate(obs, 0.0)

import random


class HeraldsTallyEnv:
    def __init__(self):
        self.n = 6
        self.max_steps = 10
        self.rng = None
        self.hats = []
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.hats = [self.rng.choice(['G', 'S']) for _ in range(self.n)]
        self.steps = 0
        self.done = False
        obs = (
            "Six nobles stand in a line, numbered 1 to 6 left to right. Each wears a "
            "hidden hat, Gold ('G') or Silver ('S'). Every noble can see all the other "
            "nobles' hats but not their own; you can see none of them directly.\n"
            "On each turn choose ONE action:\n"
            "  ask <n> left   -- noble n truthfully states how many Gold hats they see "
            "among the nobles standing to their left (lower numbers).\n"
            "  ask <n> right  -- noble n truthfully states how many Gold hats they see "
            "among the nobles standing to their right (higher numbers).\n"
            "  guess <c1> <c2> <c3> <c4> <c5> <c6> -- submit your final answer for all "
            "six hats in order (each ci is G or S). This ends the episode immediately.\n"
            f"You have {self.max_steps} actions total. Gather reports, then guess once "
            "you are confident."
        )
        return obs, {}

    def step(self, action):
        if self.done:
            return "The episode has already ended.", 0.0, True, False, {}

        self.steps += 1
        action = (action or "").strip()
        parts = action.split()

        if len(parts) == 3 and parts[0].lower() == 'ask':
            n = None
            try:
                n = int(parts[1])
            except ValueError:
                pass
            side = parts[2].lower()
            if n is None or not (1 <= n <= self.n) or side not in ('left', 'right'):
                obs = "Malformed ask. Use: ask <1-6> left|right"
                return obs, 0.0, False, self.steps >= self.max_steps, {}
            idx = n - 1
            if side == 'left':
                count = sum(1 for h in self.hats[:idx] if h == 'G')
                obs = f"Noble {n} says: 'I see {count} Gold hat(s) to my left.'"
            else:
                count = sum(1 for h in self.hats[idx + 1:] if h == 'G')
                obs = f"Noble {n} says: 'I see {count} Gold hat(s) to my right.'"
            return obs, 0.0, False, self.steps >= self.max_steps, {}

        if len(parts) == 7 and parts[0].lower() == 'guess':
            guesses = [p.upper() for p in parts[1:]]
            if any(g not in ('G', 'S') for g in guesses):
                obs = "Malformed guess. Each of the 6 values must be G or S."
                return obs, 0.0, False, self.steps >= self.max_steps, {}
            correct = sum(1 for g, h in zip(guesses, self.hats) if g == h)
            reward = correct / self.n
            self.done = True
            obs = (
                f"Final guess recorded: {' '.join(guesses)}. You correctly identified "
                f"{correct}/{self.n} hats."
            )
            return obs, reward, True, False, {}

        obs = "Unrecognized action. Use 'ask <1-6> left|right' or 'guess <6 letters>'."
        return obs, 0.0, False, self.steps >= self.max_steps, {}

import random
import re


class TwoRitesAlmanacEnv:
    """Infer two hidden periodic festival calendars from probed days,
    then predict their occurrence at three held-out future dates."""

    CAL_LEN = 30
    MAX_STEPS = 10
    PERIOD_CHOICES = (3, 4, 5)

    def __init__(self):
        self.rng = None
        self.p1 = self.a1 = None
        self.p2 = self.a2 = None
        self.holdout = None
        self.step_count = 0
        self.terminated = False

    def _ember(self, day):
        return day % self.p1 == self.a1

    def _frost(self, day):
        return day % self.p2 == self.a2

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.p1 = self.rng.choice(self.PERIOD_CHOICES)
        self.a1 = self.rng.randrange(self.p1)
        self.p2 = self.rng.choice(self.PERIOD_CHOICES)
        self.a2 = self.rng.randrange(self.p2)
        self.holdout = sorted(self.rng.sample(range(31, 46), 3))
        self.step_count = 0
        self.terminated = False

        obs = (
            "ALMANAC OF TWO RITES\n"
            "Two festivals, Ember Rite and Frost Rite, each recur on a hidden "
            "fixed period with a hidden phase (each period is one of 3, 4, or "
            "5 days). A day may show either, both, or neither festival.\n\n"
            f"You may query any calendar day from 1 to {self.CAL_LEN} to see "
            "which festivals occur that day. You have "
            f"{self.MAX_STEPS} total actions (queries plus your final "
            "submission).\n\n"
            "ACTION FORMATS:\n"
            "  QUERY <day>            -- e.g. QUERY 7\n"
            "  SUBMIT d1=<code> d2=<code> d3=<code>\n"
            "    where <code> is one of E, F, EF, N (Ember only, Frost only, "
            "both, neither)\n\n"
            f"Your final SUBMIT must cover exactly these three future days, "
            f"in any order: {', '.join(str(d) for d in self.holdout)}.\n"
            "SUBMIT ends the episode; reward is granted per correctly "
            "predicted festival-bit across the three days."
        )
        return obs, {}

    def _corrective(self, msg):
        remaining = self.MAX_STEPS - self.step_count
        return f"{msg} ({remaining} actions remaining.)", 0.0, False, False, {}

    def step(self, action):
        if self.terminated:
            return "Episode already finished.", 0.0, True, False, {}

        self.step_count += 1
        text = (action or "").strip()

        m = re.match(r"^QUERY\s+(\d+)$", text, re.IGNORECASE)
        if m:
            day = int(m.group(1))
            if not (1 <= day <= self.CAL_LEN):
                return self._checked_truncate(
                    f"Invalid day. Choose a day from 1 to {self.CAL_LEN}."
                )
            e = self._ember(day)
            f = self._frost(day)
            if e and f:
                label = "Ember YES, Frost YES"
            elif e:
                label = "Ember YES, Frost NO"
            elif f:
                label = "Ember NO, Frost YES"
            else:
                label = "Ember NO, Frost NO"
            remaining = self.MAX_STEPS - self.step_count
            obs = f"Day {day}: {label}. ({remaining} actions remaining.)"
            if remaining <= 0:
                return obs, 0.0, False, True, {}
            return obs, 0.0, False, False, {}

        m = re.match(r"^SUBMIT\s+(.+)$", text, re.IGNORECASE)
        if m:
            tokens = m.group(1).split()
            parsed = {}
            valid = True
            for tok in tokens:
                tm = re.match(r"^(\d+)=([A-Za-z]{1,2})$", tok)
                if not tm:
                    valid = False
                    break
                day = int(tm.group(1))
                code = tm.group(2).upper()
                if code in ("FE",):
                    code = "EF"
                if code not in ("E", "F", "EF", "N"):
                    valid = False
                    break
                parsed[day] = code
            if not valid or sorted(parsed.keys()) != self.holdout:
                return self._checked_truncate(
                    "Malformed SUBMIT. Provide exactly the three listed "
                    "days, each as day=CODE with CODE in {E, F, EF, N}."
                )

            correct_bits = 0
            for day in self.holdout:
                code = parsed[day]
                pred_e = "E" in code
                pred_f = "F" in code
                if pred_e == self._ember(day):
                    correct_bits += 1
                if pred_f == self._frost(day):
                    correct_bits += 1

            reward = correct_bits / (2 * len(self.holdout))
            self.terminated = True
            obs = (
                f"Submission graded: {correct_bits}/{2 * len(self.holdout)} "
                "festival-bits correct across the three days."
            )
            return obs, reward, True, False, {}

        return self._checked_truncate(
            "Unrecognized action. Use 'QUERY <day>' or "
            "'SUBMIT d1=<code> d2=<code> d3=<code>'."
        )

    def _checked_truncate(self, msg):
        obs, reward, terminated, truncated, info = self._corrective(msg)
        if self.step_count >= self.MAX_STEPS:
            return obs, reward, terminated, True, info
        return obs, reward, terminated, truncated, info

import random
import itertools


class LadderRungBazaarEnv:
    def __init__(self):
        self.rng = None
        self.heights = []
        self.prices = []
        self.tier_lo = []
        self.tier_hi = []
        self.budget = 0
        self.inspected = set()
        self.inspections_used = 0
        self.max_inspections = 2
        self.step_count = 0
        self.max_steps = 10
        self.done = False
        self.optimal_height = 0

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        n = 4
        self.heights = self.rng.sample(range(3, 10), n)
        self.tier_lo = []
        self.tier_hi = []
        self.prices = []
        for _ in range(n):
            lo = self.rng.randint(2, 7)
            hi = lo + 3
            price = self.rng.randint(lo, hi)
            self.tier_lo.append(lo)
            self.tier_hi.append(hi)
            self.prices.append(price)
        total = sum(self.prices)
        frac = self.rng.uniform(0.45, 0.65)
        budget = int(round(total * frac))
        budget = max(min(self.prices), min(budget, total - 1))
        self.budget = budget

        self.optimal_height = 0
        for r in range(n + 1):
            for combo in itertools.combinations(range(n), r):
                cost = sum(self.prices[i] for i in combo)
                if cost <= self.budget:
                    h = sum(self.heights[i] for i in combo)
                    if h > self.optimal_height:
                        self.optimal_height = h

        self.inspected = set()
        self.inspections_used = 0
        self.step_count = 0
        self.done = False

        lines = [
            "LADDER RUNG BAZAAR",
            f"You have a budget of ${self.budget}. Buy a subset of the 4 rungs below to build "
            "the tallest ladder you can WITHOUT exceeding budget.",
            "Each rung's height is known; its exact price is hidden behind a tier range.",
        ]
        for i in range(n):
            lines.append(
                f"  Rung {i+1}: height={self.heights[i]}, price tier ${self.tier_lo[i]}-${self.tier_hi[i]}"
            )
        lines.append(
            f"You may INSPECT at most {self.max_inspections} rungs to learn their exact price."
        )
        lines.append("Actions:")
        lines.append("  INSPECT <n>   — reveal the exact price of rung n (uses one of your inspections)")
        lines.append("  SUBMIT <list> — end the episode and buy the listed rungs, e.g. 'SUBMIT 1,3' or 'SUBMIT NONE'")
        lines.append(f"You have {self.max_steps} actions total (inspections + the final submit).")
        obs = "\n".join(lines)
        info = {"budget": self.budget, "heights": list(self.heights)}
        return obs, info

    def _rung_status(self):
        parts = []
        for i in range(4):
            if i in self.inspected:
                parts.append(f"Rung {i+1}: height={self.heights[i]}, price=${self.prices[i]} (known)")
            else:
                parts.append(
                    f"Rung {i+1}: height={self.heights[i]}, price tier ${self.tier_lo[i]}-${self.tier_hi[i]} (unknown)"
                )
        return "\n".join(parts)

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.step_count += 1
        text = (action or "").strip().upper()

        if text.startswith("INSPECT"):
            rest = text[len("INSPECT"):].strip()
            digits = "".join(ch for ch in rest if ch.isdigit())
            if not digits:
                obs = "Malformed action. Use 'INSPECT <n>' with n from 1 to 4.\n" + self._rung_status()
                return obs, 0.0, False, self.step_count >= self.max_steps, {}
            n = int(digits)
            if n < 1 or n > 4:
                obs = f"Rung {n} does not exist. Choose a rung from 1 to 4.\n" + self._rung_status()
                return obs, 0.0, False, self.step_count >= self.max_steps, {}
            idx = n - 1
            if self.inspections_used >= self.max_inspections and idx not in self.inspected:
                obs = (
                    f"No inspections remaining ({self.max_inspections} used). "
                    "You must decide using known info or SUBMIT.\n" + self._rung_status()
                )
                return obs, 0.0, False, self.step_count >= self.max_steps, {}
            if idx not in self.inspected:
                self.inspected.add(idx)
                self.inspections_used += 1
            remaining = self.max_inspections - self.inspections_used
            obs = (
                f"Rung {n} price revealed: ${self.prices[idx]}. Inspections remaining: {remaining}.\n"
                + self._rung_status()
            )
            truncated = self.step_count >= self.max_steps
            if truncated:
                self.done = True
                obs += "\nStep limit reached with no purchase made."
                return obs, 0.0, False, True, {}
            return obs, 0.0, False, False, {}

        if text.startswith("SUBMIT"):
            rest = text[len("SUBMIT"):].strip()
            if rest == "NONE" or rest == "":
                chosen = set()
            else:
                nums = re.findall(r"\d+", rest)
                if not nums:
                    obs = "Malformed SUBMIT. List rung numbers separated by commas/spaces, or 'SUBMIT NONE'.\n" + self._rung_status()
                    return obs, 0.0, False, self.step_count >= self.max_steps, {}
                chosen = set()
                invalid = False
                for tok in nums:
                    v = int(tok)
                    if v < 1 or v > 4:
                        invalid = True
                        continue
                    chosen.add(v - 1)
                if invalid:
                    obs = "One or more rung numbers are out of range (1-4). Try again.\n" + self._rung_status()
                    return obs, 0.0, False, self.step_count >= self.max_steps, {}

            cost = sum(self.prices[i] for i in chosen)
            height = sum(self.heights[i] for i in chosen)
            self.done = True

            if cost > self.budget:
                obs = (
                    f"Purchase FAILED: chosen rungs cost ${cost}, over your ${self.budget} budget. "
                    "The ladder could not be bought."
                )
                return obs, 0.0, True, False, {"feasible": False, "cost": cost, "height": height}

            reward = 0.2
            ratio = (height / self.optimal_height) if self.optimal_height > 0 else 1.0
            tier_note = "feasible only"
            if ratio >= 0.999:
                reward += 0.8
                tier_note = "optimal"
            elif ratio >= 0.8:
                reward += 0.5
                tier_note = "near-optimal"

            obs = (
                f"Purchase SUCCESSFUL: cost=${cost} (budget ${self.budget}), ladder height={height}. "
                f"Best possible height under this budget was {self.optimal_height} ({tier_note}). "
                f"Total reward: {reward:.2f}."
            )
            return obs, reward, True, False, {
                "feasible": True,
                "cost": cost,
                "height": height,
                "optimal_height": self.optimal_height,
            }

        obs = (
            "Unrecognized action. Use 'INSPECT <n>' or 'SUBMIT <rung numbers or NONE>'.\n"
            + self._rung_status()
        )
        truncated = self.step_count >= self.max_steps
        if truncated:
            self.done = True
            obs += "\nStep limit reached with no purchase made."
        return obs, 0.0, False, truncated, {}


import re

import random


class FaceDownParityBridgeEnv:
    """Six face-down cards, each secretly marked ODD or EVEN. One PEEK
    anchors a single card's true mark; COMPARE reveals only the relation
    (SAME/DIFFERENT mark) between two cards. The solver must chain relations
    from the anchor to deduce every card's mark, then submit one GUESS."""

    CARD_COUNT = 6
    MAX_STEPS = 10

    def _intro(self):
        cards = ", ".join(str(i) for i in range(1, self.CARD_COUNT + 1))
        return (
            "Six face-down cards are laid out, labeled " + cards + ". "
            "Each card is secretly marked ODD or EVEN. Identify every "
            "card's mark within 10 total actions.\n\n"
            "Actions (exact formats):\n"
            "  PEEK <card>            - reveal one card's TRUE mark. "
            "Usable only ONCE in the whole episode.\n"
            "  COMPARE <a> <b>        - reveal whether cards a and b have "
            "the SAME mark or a DIFFERENT mark. Usable any number of "
            "times, a and b must be distinct card labels.\n"
            "  GUESS <m1> <m2> <m3> <m4> <m5> <m6> - submit your final "
            "mark (O or E) for cards 1..6 in order. This ends the episode "
            "immediately; reward is the fraction of the 6 marks you got "
            "right.\n\n"
            "You have 10 steps total, including the final GUESS."
        )

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        while True:
            self.marks = [self.rng.choice(["O", "E"]) for _ in range(self.CARD_COUNT)]
            if len(set(self.marks)) > 1:
                break
        self.peek_used = False
        self.step_count = 0
        self.done = False
        return self._intro(), {}

    def _clamp_truncate(self, terminated):
        truncated = (not terminated) and self.step_count >= self.MAX_STEPS
        if truncated:
            self.done = True
        return truncated

    def _invalid(self, message):
        truncated = self._clamp_truncate(False)
        return message, 0.0, False, truncated, {}

    def _valid_card(self, token):
        return token.isdigit() and 1 <= int(token) <= self.CARD_COUNT

    def step(self, action):
        self.step_count += 1
        parts = action.strip().split()

        if not parts:
            return self._invalid(
                "Empty action. Use PEEK <card>, COMPARE <a> <b>, or "
                "GUESS <6 marks>. Step still counted."
            )

        cmd = parts[0].upper()

        if cmd == "PEEK":
            if len(parts) != 2 or not self._valid_card(parts[1]):
                return self._invalid(
                    "Malformed PEEK. Format: PEEK <card 1-6>. Step counted, "
                    "no reward."
                )
            if self.peek_used:
                return self._invalid(
                    "PEEK already used this episode; it cannot be repeated. "
                    "Use COMPARE to keep gathering evidence. Step counted, "
                    "no reward."
                )
            cid = int(parts[1])
            self.peek_used = True
            mark = self.marks[cid - 1]
            obs = "Card " + str(cid) + " is truly marked " + mark + "."
            truncated = self._clamp_truncate(False)
            return obs, 0.0, False, truncated, {}

        if cmd == "COMPARE":
            if len(parts) != 3 or not self._valid_card(parts[1]) or not self._valid_card(parts[2]):
                return self._invalid(
                    "Malformed COMPARE. Format: COMPARE <card 1-6> "
                    "<card 1-6>. Step counted, no reward."
                )
            a, b = int(parts[1]), int(parts[2])
            if a == b:
                return self._invalid(
                    "COMPARE requires two DIFFERENT cards. Step counted, "
                    "no reward."
                )
            relation = "SAME" if self.marks[a - 1] == self.marks[b - 1] else "DIFFERENT"
            obs = "Cards " + str(a) + " and " + str(b) + " have " + relation + " marks."
            truncated = self._clamp_truncate(False)
            return obs, 0.0, False, truncated, {}

        if cmd == "GUESS":
            if len(parts) != self.CARD_COUNT + 1:
                return self._invalid(
                    "Malformed GUESS. Format: GUESS <m1> <m2> <m3> <m4> "
                    "<m5> <m6>, one O or E per card in order. Step "
                    "counted, no reward."
                )
            guesses = [p.upper() for p in parts[1:]]
            if not all(g in ("O", "E") for g in guesses):
                return self._invalid(
                    "Each guess must be O or E. Step counted, no reward."
                )
            correct = sum(1 for g, m in zip(guesses, self.marks) if g == m)
            reward = correct / float(self.CARD_COUNT)
            self.done = True
            truth = " ".join(self.marks)
            obs = (
                "Final guess scored " + str(correct) + "/" + str(self.CARD_COUNT)
                + " correct. True marks were: " + truth + "."
            )
            return obs, reward, True, False, {}

        return self._invalid(
            "Unknown command '" + parts[0] + "'. Use PEEK, COMPARE, or "
            "GUESS. Step counted, no reward."
        )

import random


class MirrorRotorEnv:
    ALPHABET = ['A', 'B', 'C', 'D']
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.rot_map = {}
        self.targets = []
        self.step_count = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.rot_map = self._gen_rot_map()
        self.targets = self._gen_targets()
        self.step_count = 0
        self.done = False
        lines = [
            "You are analyzing MIRROR-GLYPHS: strings built from glyphs A, B, C, D.",
            "A hidden pairing rule links each glyph to a rotation partner (possibly itself) -- like rotating a printed character 180 degrees, the way '6' becomes '9' while 'S' stays 'S'.",
            "A string is MIRROR-SYMMETRIC if replacing every glyph with its rotation partner and reading the result backward reproduces the original string exactly.",
            "Example of the mechanic (not the real rule): if P were paired with Q, then 'PQ' and 'QP' would each be mirror-symmetric, but 'PP' would only be mirror-symmetric if P were paired with itself.",
            "",
            "Classify these 4 target strings as SYM or ASYM under the hidden rule:",
        ]
        for i, (s, _) in enumerate(self.targets, 1):
            lines.append(f"  {i}. {s}")
        lines += [
            "",
            "You may NOT probe the target strings directly -- test other glyph strings to learn the hidden pairing instead.",
            "Actions (budget: 10 steps total):",
            "  TEST <string>   -- 1 to 4 characters from A/B/C/D, e.g. TEST AC -- reports whether that probe string is mirror-symmetric.",
            "  SUBMIT <c1> <c2> <c3> <c4> -- e.g. SUBMIT SYM ASYM SYM ASYM -- final classification of the 4 targets in order; ends the episode.",
            "Each correct classification is worth 0.25 reward (max total 1.0). A malformed action costs a step and earns no reward.",
        ]
        return "\n".join(lines), {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        parts = (action or "").strip().split()
        if not parts:
            return self._malformed("Empty action. Use 'TEST <string>' or 'SUBMIT <c1> <c2> <c3> <c4>'.")

        cmd = parts[0].upper()

        if cmd == "TEST":
            if len(parts) != 2:
                return self._malformed("TEST needs exactly one glyph string, e.g. TEST AC.")
            query = parts[1].upper()
            if not (1 <= len(query) <= 4) or any(c not in self.ALPHABET for c in query):
                return self._malformed("TEST string must be 1-4 characters using only A, B, C, D.")
            if any(query == s for s, _ in self.targets):
                return self._malformed("Cannot TEST a target string directly -- probe a different string.")
            self.step_count += 1
            result = self._is_symmetric(query)
            obs = f"TEST '{query}': {'MIRROR-SYMMETRIC' if result else 'not symmetric'} under the hidden rule."
            return self._maybe_truncate(obs)

        if cmd == "SUBMIT":
            if len(parts) != 5:
                return self._malformed("SUBMIT needs exactly 4 labels, e.g. SUBMIT SYM ASYM SYM ASYM.")
            labels = [p.upper() for p in parts[1:5]]
            if any(l not in ("SYM", "ASYM") for l in labels):
                return self._malformed("Each label must be SYM or ASYM.")
            self.step_count += 1
            correct = 0
            report = []
            for i, ((s, truth), guess) in enumerate(zip(self.targets, labels), 1):
                truth_label = "SYM" if truth else "ASYM"
                is_right = guess == truth_label
                correct += int(is_right)
                report.append(f"  {i}. {s}: guessed {guess}, actual {truth_label} -- {'correct' if is_right else 'wrong'}")
            reward = 0.25 * correct
            self.done = True
            obs = "Results:\n" + "\n".join(report) + f"\nScore: {correct}/4 correct."
            return obs, reward, True, False, {"correct": correct}

        return self._malformed("Unrecognized action. Use 'TEST <string>' or 'SUBMIT <c1> <c2> <c3> <c4>'.")

    def _malformed(self, message):
        self.step_count += 1
        return self._maybe_truncate(message, reward=0.0)

    def _maybe_truncate(self, obs, reward=0.0):
        if self.step_count >= self.MAX_STEPS:
            self.done = True
            return obs + "\nStep limit reached without a SUBMIT -- episode over.", reward, False, True, {}
        return obs, reward, False, False, {}

    def _is_symmetric(self, s):
        n = len(s)
        for i in range(n):
            if self.rot_map[s[i]] != s[n - 1 - i]:
                return False
        return True

    def _gen_rot_map(self):
        for _ in range(30):
            letters = list(self.ALPHABET)
            self.rng.shuffle(letters)
            mapping = {}
            i = 0
            while i < len(letters):
                remaining = len(letters) - i
                if remaining >= 2 and self.rng.random() < 0.6:
                    a, b = letters[i], letters[i + 1]
                    mapping[a] = b
                    mapping[b] = a
                    i += 2
                else:
                    mapping[letters[i]] = letters[i]
                    i += 1
            if any(mapping[x] != x for x in mapping):
                return mapping
        mapping = {c: c for c in self.ALPHABET}
        mapping[self.ALPHABET[0]] = self.ALPHABET[1]
        mapping[self.ALPHABET[1]] = self.ALPHABET[0]
        return mapping

    def _gen_targets(self):
        best = None
        for _ in range(200):
            candidate = []
            for _ in range(4):
                length = self.rng.randint(2, 4)
                s = ''.join(self.rng.choice(self.ALPHABET) for _ in range(length))
                candidate.append((s, self._is_symmetric(s)))
            strings = [s for s, _ in candidate]
            labels = [t for _, t in candidate]
            if len(set(strings)) == 4 and any(labels) and not all(labels):
                return candidate
            best = candidate
        return best
